 if(st.loading&&!st.me){$('#m').innerHTML=`<div class="auth" style="align-items:center;justify-content:center"><div class="logo">${ic('est')} Pistea</div><small>Cargando…</small></div>`;$('#nav').style.display='none';return}
 if(st.offline&&!st.me){$('#m').innerHTML=`<div class="auth" style="justify-content:center"><div class="logo">${ic('est')} Pistea</div><h1>Sin conexión</h1><p class="mu" style="margin:8px 0 20px">No llegamos al servidor. Tu sesión sigue abierta: en cuanto vuelva la conexión entras directamente.</p><button class="btn" data-c="boot">Reintentar</button></div>`;$('#nav').style.display='none';return}
 if(!st.me){$('#m').innerHTML=authView();$('#nav').style.display='none';return}
 $('#nav').style.display='';$('#m').innerHTML=(st.toast?`<div class="toast">${esc(st.toast)}</div>`:'')+V[st.tab]();
