function pickAvatar(input){const f=input.files&&input.files[0];if(!f)return;if(!/^image\/(jpeg|png|webp)$/i.test(f.type)){flash('Solo se admiten fotos JPEG, PNG o WebP.');return}const r=new FileReader();r.onload=e=>{const img=new Image();img.onload=async ()=>{const c=document.createElement('canvas'),s=Math.min(img.width,img.height);c.width=300;c.height=300;c.getContext('2d').drawImage(img,(img.width-s)/2,(img.height-s)/2,s,s,0,0,300,300);try{const res=await api('avatar',{body:{image:c.toDataURL('image/webp',0.85)}});st.user.avatar=res.avatar;render();flash('Foto de perfil actualizada.')}catch(err){flash(err.message)}};img.src=e.target.result};r.readAsDataURL(f)}
function editProfile(){const u=st.user;ov(`<div class="top" style="padding-top:60px"><h1>Editar perfil</h1></div><form data-s="saveProfile|@e"><div style="display:flex;gap:14px;align-items:center;margin-bottom:16px"><span class="av" style="width:60px;height:60px;font-size:20px;${u.avatar?`background-image:url(${esc(u.avatar)});background-size:cover;background-position:center;color:transparent`:''}">${ini(u.alias)}</span><div><button type="button" class="btn gh" style="padding:8px 14px;font-size:13px" data-c="pickFile">Cambiar foto</button>${u.avatar?`<button type="button" class="link" style="color:var(--r);font-size:12.5px;margin-left:10px" data-c="delAvatar">Quitar foto</button>`:''}</div></div><label>Nombre público</label><input id="ed-al" value="${esc(u.alias)}" maxlength="24" required><label>Edad (años)</label><input id="ed-ag" type="number" min="14" max="120" value="${u.age||''}" placeholder="Ej: 28"><small style="color:var(--mu);display:block;margin-top:4px">Mínimo 14 años por ley (art. 7 LOPDGDD 3/2018).</small><label>Modalidad</label><select id="ed-mod" style="width:100%;background:var(--s1);border:1px solid var(--ln);border-radius:10px;padding:12px;color:var(--tx);font:inherit"><option value="ski" ${u.modality==='ski'?'selected':''}>Esquí</option><option value="snowboard" ${u.modality==='snowboard'?'selected':''}>Snowboard</option><option value="ambos" ${u.modality==='ambos'?'selected':''}>Esquí y snowboard</option></select><label>Nivel</label><select id="ed-lvl" style="width:100%;background:var(--s1);border:1px solid var(--ln);border-radius:10px;padding:12px;color:var(--tx);font:inherit"><option value="debutante" ${u.level==='debutante'?'selected':''}>Debutante (pistas verdes)</option><option value="intermedio" ${u.level==='intermedio'?'selected':''}>Intermedio (pistas azules)</option><option value="avanzado" ${u.level==='avanzado'?'selected':''}>Avanzado (pistas rojas)</option><option value="experto" ${u.level==='experto'?'selected':''}>Experto (pistas negras y freeride)</option></select><label>Estación habitual</label><select id="ed-sh" style="width:100%;background:var(--s1);border:1px solid var(--ln);border-radius:10px;padding:12px;color:var(--tx);font:inherit"><option value="">Sin estación fija</option>${S.map(s=>`<option value="${s.id}" ${u.station_home===s.id?'selected':''}>${esc(s.n)} (${s.z})</option>`).join('')}</select><label>Biografía / Presentación</label><textarea id="ed-bio" maxlength="200" rows="3" style="width:100%;background:var(--s1);border:1px solid var(--ln);border-radius:10px;padding:12px;color:var(--tx);font:inherit;resize:none" placeholder="Cuenta cómo esquías: tu pista favorita, tu estación…">${esc(u.bio||'')}</textarea><button class="btn" id="ed-sb" style="margin-top:20px">Guardar cambios</button></form>`)}
async function saveProfile(e){e.preventDefault();$('#ed-sb').disabled=true;const alias=$('#ed-al').value.trim(),age=$('#ed-ag').value?parseInt($('#ed-ag').value,10):null,modality=$('#ed-mod').value,level=$('#ed-lvl').value,station_home=$('#ed-sh').value||null,bio=$('#ed-bio').value.trim();try{const r=await api('me',{method:'POST',body:{alias,age,modality,level,station_home,bio}});st.user=r.user;st.me.user=r.user;ov0();render();flash('Perfil actualizado con éxito.')}catch(err){flash(err.message);$('#ed-sb').disabled=false}return false}
async function delAvatar(){if(!confirm('¿Eliminar tu foto de perfil?'))return;try{await api('avatar',{method:'DELETE'});st.user.avatar=null;ov0();render();flash('Foto de perfil eliminada.')}catch(err){flash(err.message)}}
async function exportData(){try{const res=await fetch('/api/me/export',{credentials:'same-origin'});if(!res.ok)throw new Error('Error al descargar');const b=await res.blob(),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download=`pistea-datos-${st.user.alias.replace(/[^a-zA-Z0-9]/g,'')}.json`;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);flash('Datos descargados en formato oficial JSON.')}catch(e){flash(e.message)}}
