function ficha(i){const s=SM[i],info=st.stats[i]||{leaders:[],skiers:0};
 const fc=FC[i];ov(`<div class="photo" style="background-image:${photo(i)}"><div class="eyebrow">${s.z}</div><h1>${s.n}</h1></div>${fc?`<p class="credit">${fc.ambiente?"Imagen de ambiente de la zona, no de la estación. ":""}Foto: ${esc(fc.autor)}, ${esc(fc.licencia)}, <a href="${esc(fc.url)}" target="_blank" rel="noopener">Wikimedia Commons</a></p>`:''}
 ${SI[i]?`<div class="kpis" style="margin:14px 0"><div><b>${SI[i].pistas}</b><small>pistas</small></div><div><b>${SI[i].remontes}</b><small>remontes</small></div><div><b>${info.skiers}</b><small>${info.skiers===1?'esquiador':'esquiadores'}</small></div></div>`:''}
 <div id="m3d" class="map map3d" style="height:210px;margin-top:0;background-image:linear-gradient(180deg,rgba(9,30,52,.1),rgba(9,30,52,.72)),url(/img/${i}.webp)" data-c="load3d|${i}" role="button" tabindex="0"><div>${ic('map')}<b>Ver la estación en 3D</b><small>Relieve, pistas y remontes reales</small></div></div>
 <p class="credit">Pistas y remontes según OpenStreetMap (recuento aproximado). Mapa: relieve del IGN e imagen Copernicus Sentinel-2.</p><button class="btn go" style="margin-top:14px" data-c="traquear|${i}">${ic('go')}Grabar mi día aquí</button>
 <h2>Líderes de la temporada</h2>${info.leaders.length?info.leaders.map((x,k)=>`<div class="row"><span class="pos">${k+1}</span>${av(x.alias)}<b style="font-weight:600">${esc(x.alias)}</b><span class="val">${fmt(x.v)} m</span></div>`).join(''):'<div class="empty">Nadie ha esquiado aquí todavía. Sé el primero.</div>'}
 <button class="btn gh" style="margin-top:14px" data-c="rankOf|${s.n}">Ver clasificación completa</button>`)}
